import{_ as a,o as e,c as i,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const h=JSON.parse('{"title":"ImGui API ガイド","description":"","frontmatter":{"lang":"ja","sourcePath":"docs/imgui/api.ja.md"},"headers":[],"relativePath":"ja/imgui/api.md","filePath":"ja/imgui/api.md"}'),l={name:"ja/imgui/api.md"};function d(o,t,n,s,c,m){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="imgui-api-ガイド" tabindex="-1">ImGui API ガイド <a class="header-anchor" href="#imgui-api-ガイド" aria-label="Permalink to &quot;ImGui API ガイド&quot;">​</a></h1><p>目的別ガイドで使い方を学んだ後、<a href="/ja/reference/imgui/" target="_self">API リファレンス</a>で引数や戻り値を確認します。一覧の概要で操作を探し、詳細ページで使用上の注意、パラメーター、戻り値、ネイティブリソースの寿命を読みます。</p><h2 id="名前空間を選ぶ" tabindex="-1">名前空間を選ぶ <a class="header-anchor" href="#名前空間を選ぶ" aria-label="Permalink to &quot;名前空間を選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>入口</th><th>ガイド</th></tr></thead><tbody><tr><td>ウィンドウ連携</td><td>SFML.Init、ProcessEvent、Update、Render、Shutdown</td><td><a href="/ja/imgui/getting-started">開始</a></td></tr><tr><td>コントロール宣言</td><td>ImGui.Button、Checkbox、SliderFloatEx</td><td><a href="/ja/imgui/widgets">状態</a></td></tr><tr><td>パネル構成</td><td>BeginChild、BeginTable、メニュー、ポップアップ</td><td><a href="/ja/imgui/layout">レイアウト</a></td></tr><tr><td>UTF-8 とコールバック</td><td>InputTextEx、ListBoxCallbackEx、PlotLinesCallbackEx</td><td><a href="/ja/imgui/callbacks">入力</a></td></tr><tr><td>フォントとスタイル</td><td>getFontAtlas、getStyleColors、SFML.GetStyle</td><td><a href="/ja/imgui/fonts">フォント</a></td></tr><tr><td>図形とウィンドウ切り替え</td><td>ImGui.GetWindowDrawList、SFML.SetCurrentWindow</td><td><a href="/ja/imgui/rendering">描画</a></td></tr></tbody></table><h2 id="javascript-の契約として読む" tabindex="-1">JavaScript の契約として読む <a class="header-anchor" href="#javascript-の契約として読む" aria-label="Permalink to &quot;JavaScript の契約として読む&quot;">​</a></h2><p><a href="/ja/reference/imgui/functions/ImGui.SliderFloatEx.html" target="_self">SliderFloatEx</a>は書き込み可能な Float32Array、上下限、書式、フラグを受け取ります。boolean は編集の発生で、値は配列にあります。ネイティブの引数名によって JavaScript 数値が書き込み先になるわけではありません。</p><p>Button は既定サイズ、ButtonEx はサイズ指定です。PushStyleVar はスカラー、PushStyleVarVec2 はベクトルです。Ex が常にコールバックを意味するとは限らず、シグネチャを確認します。</p><p>ImVec2Like は <code>[ x, y ]</code> や <code>{ x, y }</code> などの値を受け取ります。編集用数値ポインターには指定された型付き配列が必要です。ImGuiInputTextCallbackData などの構造体ハンドルは、バインディングが返す型付きの不透明オブジェクトです。テクスチャ ID と生ポインター引数は bigint であり、構造体ハンドルとは交換できません。推測したアドレスで作らないでください。</p><p>ImGui.GetIO/GetStyle はネイティブハンドル、SFML.GetIO/GetStyle は現在のウィンドウの便利な書き込みビューです。ハンドルを要求するヘルパーにビューを渡せません。</p><h2 id="呼び出し前の確認" tabindex="-1">呼び出し前の確認 <a class="header-anchor" href="#呼び出し前の確認" aria-label="Permalink to &quot;呼び出し前の確認&quot;">​</a></h2><ol><li>初期化済みコンテキスト、活動フレーム、可視の親が必要か。</li><li>引数はコピー、直接変更、借用のどれか。</li><li>null は閉じるボタンなどの機能を無効にするか。</li><li>boolean は操作、変更、選択、可視性のどれか。</li><li>対応する End/Pop とその条件は何か。</li><li>戻されたハンドルやビューはいつまで有効か。</li></ol><p>TypeScript の補完と実装調査には<a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/index.ts" target="_blank" rel="noreferrer">公開エクスポート</a>、<a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/sfml.ts" target="_blank" rel="noreferrer">SFML 連携</a>、<a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/imgui/index.ts" target="_blank" rel="noreferrer">ImGui モジュール</a>を参照します。</p><p>説明は宣言の隣で英・中・日・韓の概要と詳細を管理し、TypeDoc が直接読み取ります。問題報告には関数、言語、期待する JavaScript 呼び出し、実際の結果を含めてください。</p>',13)])])}const p=a(l,[["render",d]]);export{h as __pageData,p as default};
